const glyphCache = {};
function glyph(ch) {
    if (glyphCache[ch]) return glyphCache[ch];
    const g = FONT.g[ch];
    if (!g) return null;
    return (glyphCache[ch] = { w: g.w, h: FONT.h, p: g.p, adv: g.a, a: zlib.inflateSync(Buffer.from(g.d, 'base64')) });
}

/* ═══════════ الرسم ═══════════ */
const W = 1000, H = 490;
const clamp01 = v => (v < 0 ? 0 : v > 1 ? 1 : v);
const mix = (a, b, t) => a + (b - a) * t;
const lerpC = (c1, c2, t) => [mix(c1[0], c2[0], t), mix(c1[1], c2[1], t), mix(c1[2], c2[2], t)];

const WHITE = [255, 255, 255];
const CYAN = [90, 214, 255];
const BLUE = [60, 130, 255];
const ICE = [190, 226, 255];
const MUTED = [140, 165, 210];
const NAVY = [5, 14, 46];
const GREEN = [52, 235, 140];

function blend(d, x, y, c, a) {
    x = Math.floor(x); y = Math.floor(y);
    if (a <= 0 || x < 0 || y < 0 || x >= W || y >= H) return;
    const i = (y * W + x) * 4;
    d[i] += (c[0] - d[i]) * a; d[i + 1] += (c[1] - d[i + 1]) * a; d[i + 2] += (c[2] - d[i + 2]) * a;
}

function sample(img, u, v) {
    const x = Math.min(img.width - 1.001, Math.max(0, u - 0.5)), y = Math.min(img.height - 1.001, Math.max(0, v - 0.5));
    const x0 = Math.floor(x), y0 = Math.floor(y), fx = x - x0, fy = y - y0, out = [0, 0, 0];
    for (const [ox, oy, wgt] of [[0, 0, (1 - fx) * (1 - fy)], [1, 0, fx * (1 - fy)], [0, 1, (1 - fx) * fy], [1, 1, fx * fy]]) {
        const i = ((y0 + oy) * img.width + (x0 + ox)) * 4;
        out[0] += img.data[i] * wgt; out[1] += img.data[i + 1] * wgt; out[2] += img.data[i + 2] * wgt;
    }
    return out;
}

/** خلفية: صورة المطور مكبّرة ومموّهة تحت طبقة داكنة زرقاء (مثل البطاقة المرجعية) */
function background(img) {
    const d = new Uint8ClampedArray(W * H * 4);
    const GW = 40, GH = 20;
    let grid = null;
    if (img && img.width && img.height) {
        grid = [];
        const s = Math.max(W / img.width, H / img.height) * 1.25;
        const ox = (img.width - W / s) / 2, oy = (img.height - H / s) / 2;
        for (let gy = 0; gy < GH; gy++) for (let gx = 0; gx < GW; gx++) {
            let r = 0, g = 0, b = 0, n = 0;
            for (let sy = 0; sy < 4; sy++) for (let sx = 0; sx < 4; sx++) {
                const px = ((gx + (sx + 0.5) / 4) / GW) * W, py = ((gy + (sy + 0.5) / 4) / GH) * H;
                const c = sample(img, ox + px / s, oy + py / s);
                r += c[0]; g += c[1]; b += c[2]; n++;
            }
            grid.push([r / n, g / n, b / n]);
        }
    }
    for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
        const t = clamp01((x / W) * 0.5 + (1 - y / H) * 0.5);
        let base = lerpC([4, 10, 34], [12, 48, 140], t);
        if (grid) {
            const fx = clamp01(x / W) * GW - 0.5, fy = clamp01(y / H) * GH - 0.5;
            const x0 = Math.max(0, Math.min(GW - 2, Math.floor(fx))), y0 = Math.max(0, Math.min(GH - 2, Math.floor(fy)));
            const tx = clamp01(fx - x0), ty = clamp01(fy - y0);
            const c = [0, 0, 0];
            for (let k = 0; k < 3; k++) {
                const top = mix(grid[y0 * GW + x0][k], grid[y0 * GW + x0 + 1][k], tx);
                const bot = mix(grid[(y0 + 1) * GW + x0][k], grid[(y0 + 1) * GW + x0 + 1][k], tx);
                c[k] = mix(top, bot, ty);
            }
            base = [base[0] * 0.55 + c[0] * 0.30, base[1] * 0.55 + c[1] * 0.32, base[2] * 0.6 + c[2] * 0.40];
        }
        const v = 1 - 0.42 * Math.pow(Math.hypot(x / W - 0.5, y / H - 0.5) * 1.3, 2);
        const i = (y * W + x) * 4;
        d[i] = Math.min(255, base[0] * v); d[i + 1] = Math.min(255, base[1] * v); d[i + 2] = Math.min(255, base[2] * v + 8); d[i + 3] = 255;
    }
    return d;
}

function glow(d, cx, cy, R, c, strength) {
    for (let y = Math.floor(cy - R); y <= Math.ceil(cy + R); y++) for (let x = Math.floor(cx - R); x <= Math.ceil(cx + R); x++) {
        const t = 1 - Math.hypot(x + 0.5 - cx, y + 0.5 - cy) / R;
        if (t > 0) blend(d, x, y, c, strength * t * t);
    }
}

/** مستطيل بزوايا دائرية. color مصفوفة أو دالة (x,y)⇒RGB. stroke>0 يرسم إطارًا فقط */
function roundRect(d, x, y, w, h, rad, color, alpha = 1, stroke = 0) {
    const cx = x + w / 2, cy = y + h / 2;
    for (let py = Math.floor(y) - 1; py <= Math.ceil(y + h) + 1; py++) for (let px = Math.floor(x) - 1; px <= Math.ceil(x + w) + 1; px++) {
        const qx = Math.abs(px + 0.5 - cx) - (w / 2 - rad), qy = Math.abs(py + 0.5 - cy) - (h / 2 - rad);
        const dist = Math.hypot(Math.max(qx, 0), Math.max(qy, 0)) + Math.min(Math.max(qx, qy), 0) - rad;
        const a = stroke ? clamp01(stroke / 2 + 0.5 - Math.abs(dist + stroke / 2)) : clamp01(0.5 - dist);
        if (a > 0) blend(d, px, py, typeof color === 'function' ? color(px, py) : color, a * alpha);
    }
}

function disc(d, cx, cy, r, c, alpha = 1) {
    for (let y = Math.floor(cy - r - 1); y <= Math.ceil(cy + r + 1); y++) for (let x = Math.floor(cx - r - 1); x <= Math.ceil(cx + r + 1); x++) {
        blend(d, x, y, c, clamp01(r + 0.5 - Math.hypot(x + 0.5 - cx, y + 0.5 - cy)) * alpha);
    }
}

function drawMask(d, m, x, y, s, c, alpha = 1) {
    const dw = Math.ceil(m.w * s), dh = Math.ceil(m.h * s);
    for (let dy = 0; dy < dh; dy++) for (let dx = 0; dx < dw; dx++) {
        let sum = 0;
        for (let sy = 0; sy < 3; sy++) for (let sx = 0; sx < 3; sx++) {
            const u = Math.min(m.w - 1, Math.floor((dx + (sx + 0.5) / 3) / s));
            const v = Math.min(m.h - 1, Math.floor((dy + (sy + 0.5) / 3) / s));
            sum += m.a[v * m.w + u];
        }
        blend(d, x + dx, y + dy, c, (sum / 9 / 255) * alpha);
    }
}

const textWidth = (str, size, spacing = 0) => {
    const s = size / FONT.size;
    const chars = [...str].filter(ch => FONT.g[ch]);
    return chars.reduce((w, ch, i) => w + FONT.g[ch].a * s + (i ? spacing : 0), 0);
};

/** يرسم نصًا إنجليزيًا. cy = مركز الحروف الكبيرة رأسيًا. align: l | c | r. يعيد العرض */
function text(d, str, x, cy, size, c, align = 'l', alpha = 1, spacing = 0) {
    const s = size / FONT.size;
    const chars = [...str].filter(ch => FONT.g[ch]);
    const total = textWidth(str, size, spacing);
    let left = align === 'r' ? x - total : align === 'c' ? x - total / 2 : x;
    const top = Math.round(cy - 0.6 * size);
    for (const ch of chars) {
        const g = glyph(ch);
        drawMask(d, g, Math.round(left - g.p * s), top, s, c, alpha);
        left += g.adv * s + spacing;
    }
    return total;
}

function glowText(d, str, x, cy, size, c, glowC, align = 'l', spacing = 0) {
    for (const [ox, oy] of [[-2, 0], [2, 0], [0, -2], [0, 2], [-2, -2], [2, 2], [-2, 2], [2, -2]]) {
        text(d, str, x + ox, cy + oy, size, glowC, align, 0.16, spacing);
    }
    return text(d, str, x, cy, size, c, align, 1, spacing);
}

const fitSize = (str, size, maxW, spacing = 0) => {
    const w = textWidth(str, size, spacing);
    return w > maxW ? Math.max(8, Math.floor(size * maxW / w)) : size;
};

/* ─────────── أيقونات صغيرة بالكود ─────────── */
const ICONS = {
    user: (u, v) => (Math.hypot(u, v + 0.3) < 0.3) || ((u / 0.62) ** 2 + ((v - 0.62) / 0.5) ** 2 < 1 && v < 0.78),
    globe: (u, v) => { const r = Math.hypot(u, v); return (r < 0.66 && r > 0.52) || (Math.abs(v) < 0.05 && r < 0.6) || (r < 0.6 && Math.abs((u / 0.28) ** 2 + (v / 0.6) ** 2 - 1) < 0.28); },
    cake: (u, v) => (Math.abs(u) < 0.6 && v > -0.35 && v < 0.55 && !(Math.abs(u) < 0.45 && v > -0.1 && v < 0.45)) || (Math.abs(u) < 0.6 && v > -0.35 && v < -0.1) || (Math.abs(u - 0.28) < 0.07 && v < -0.35 && v > -0.62) || (Math.abs(u + 0.28) < 0.07 && v < -0.35 && v > -0.62),
    crown: (u, v) => {
        if (v > 0.5 || v < -0.55) return false;
        const poly = [[-0.62, 0.5], [-0.62, -0.28], [-0.3, 0.08], [0, -0.55], [0.3, 0.08], [0.62, -0.28], [0.62, 0.5]];
        let inside = false;
        for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
            if (((poly[i][1] > v) !== (poly[j][1] > v)) && (u < (poly[j][0] - poly[i][0]) * (v - poly[i][1]) / (poly[j][1] - poly[i][1]) + poly[i][0])) inside = !inside;
        }
        return inside;
    },
    status: (u, v) => { const r = Math.hypot(u, v); return (r < 0.66 && r > 0.5) || r < 0.26; },
    bot: (u, v) => {
        const body = Math.abs(u) < 0.62 && v > -0.2 && v < 0.6;
        const eyes = Math.hypot(Math.abs(u) - 0.24, v - 0.18) < 0.13;
        const ant = (Math.abs(u) < 0.06 && v < -0.2 && v > -0.5) || Math.hypot(u, v + 0.56) < 0.12;
        return (body && !eyes) || ant;
    }
};
function icon(d, type, cx, cy, r, c, alpha = 1) {
    const f = ICONS[type]; if (!f) return;
    for (let y = Math.floor(cy - r); y <= Math.ceil(cy + r); y++) for (let x = Math.floor(cx - r); x <= Math.ceil(cx + r); x++) {
        let hit = 0;
        for (let sy = 0; sy < 3; sy++) for (let sx = 0; sx < 3; sx++) {
            if (f((x + (sx + 0.5) / 3 - cx) / r, (y + (sy + 0.5) / 3 - cy) / r)) hit++;
        }
        if (hit) blend(d, x, y, c, (hit / 9) * alpha);
    }
}

/** علم السودان: أحمر/أبيض/أسود + مثلث أخضر */
function flagSudan(d, x, y, w, h) {
    const rad = 5, cx = x + w / 2, cy = y + h / 2;
    for (let py = Math.floor(y) - 1; py <= Math.ceil(y + h) + 1; py++) for (let px = Math.floor(x) - 1; px <= Math.ceil(x + w) + 1; px++) {
        const qx = Math.abs(px + 0.5 - cx) - (w / 2 - rad), qy = Math.abs(py + 0.5 - cy) - (h / 2 - rad);
        const dist = Math.hypot(Math.max(qx, 0), Math.max(qy, 0)) + Math.min(Math.max(qx, qy), 0) - rad;
        const a = clamp01(0.5 - dist);
        if (a <= 0) continue;
        const t = (py + 0.5 - y) / h;
        let c = t < 1 / 3 ? [210, 16, 52] : t < 2 / 3 ? [255, 255, 255] : [20, 20, 20];
        const lx = (px + 0.5 - x) / h;              // المثلث الأخضر من جهة اليسار
        if (lx < 0.9 * (1 - Math.abs(2 * t - 1))) c = [0, 122, 61];
        blend(d, px, py, c, a);
    }
}

function chip(d, x, y, w, h, label, c1, c2, textColor, size, spacing) {
    roundRect(d, x, y, w, h, h / 2, (px) => lerpC(c1, c2, clamp01((px - x) / w)), 1);
    roundRect(d, x, y, w, h, h / 2, WHITE, 0.35, 1.5);
    for (let px = x + h / 2; px < x + w - h / 2; px++) blend(d, px, y + 4, WHITE, 0.28);
    text(d, label, x + w / 2, y + h / 2, size, textColor, 'c', 1, spacing);
}

function bracket(d, x, y, dx, dy, c) {
    for (let t = 0; t < 40; t++) for (let k = 0; k < 3; k++) {
        blend(d, x + dx * t, y + dy * k, c, 0.95);
        blend(d, x + dx * k, y + dy * t, c, 0.95);
    }
}

/** الصورة الشخصية داخل حلقة متوهجة. إن لم توجد صورة تُرسم شخصية بديلة */
function avatar(d, cx, cy, R, img) {
    const RING = 7, OUT = R + RING;
    glow(d, cx, cy, OUT + 46, [70, 150, 255], 0.55);
    for (let py = cy - OUT - 2; py <= cy + OUT + 2; py++) for (let px = cx - OUT - 2; px <= cx + OUT + 2; px++) {
        const dx = px + 0.5 - cx, dy = py + 0.5 - cy, dist = Math.hypot(dx, dy);
        const a = clamp01(OUT + 0.5 - dist) * clamp01(dist - (R - 1) + 0.5);
        if (a <= 0) continue;
        const ang = (Math.atan2(dy, dx) + Math.PI) / (Math.PI * 2);
        const col = ang < 0.5 ? lerpC([80, 220, 255], [150, 90, 255], ang * 2) : lerpC([150, 90, 255], [80, 220, 255], (ang - 0.5) * 2);
        blend(d, px, py, col, a);
    }
    let side = 0, ox = 0, oy = 0;
    if (img && img.width && img.height) { side = Math.min(img.width, img.height); ox = (img.width - side) / 2; oy = (img.height - side) / 2; }
    for (let py = cy - R - 1; py <= cy + R + 1; py++) for (let px = cx - R - 1; px <= cx + R + 1; px++) {
        const dist = Math.hypot(px + 0.5 - cx, py + 0.5 - cy), a = clamp01(R + 0.5 - dist);
        if (a <= 0) continue;
        let c;
        if (side) {
            c = [0, 0, 0];
            for (const [dx, dy] of [[0.25, 0.25], [0.75, 0.25], [0.25, 0.75], [0.75, 0.75]]) {
                const p = sample(img, ((px + dx - (cx - R)) / (2 * R)) * side + ox, ((py + dy - (cy - R)) / (2 * R)) * side + oy);
                c[0] += p[0] / 4; c[1] += p[1] / 4; c[2] += p[2] / 4;
            }
        } else {
            const nx = (px + 0.5 - cx) / R, ny = (py + 0.5 - cy) / R, shade = 1 - 0.25 * ((ny + 1) / 2);
            c = [30 * shade, 90 * shade, 200 * shade];
            if (nx * nx + (ny + 0.22) * (ny + 0.22) <= 0.09 || (nx / 0.62) ** 2 + ((ny - 0.72) / 0.5) ** 2 <= 1) c = [225, 238, 255];
        }
        blend(d, px, py, c, a);
    }
}

function barcode(d, x, y, w, h, seedStr) {
    let seed = 0;
    for (const ch of seedStr) seed = (seed * 31 + ch.charCodeAt(0)) >>> 0;
    const rnd = () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; };
    let px = x;
    while (px < x + w) {
        const bw = 1 + Math.floor(rnd() * 3);
        for (let i = 0; i < bw && px + i < x + w; i++) for (let py = y; py < y + h; py++) blend(d, px + i, py, ICE, 0.9);
        px += bw + 1 + Math.floor(rnd() * 2);
    }
}

/** يرسم البطاقة كاملة (1000×490) ويعيد بكسلات RGBA */
function makeCard({ name, country, age, idNum, date, img }) {
    const d = background(img);

    // إطار البطاقة وزواياها
    roundRect(d, 7, 7, W - 14, H - 14, 24, (x, y) => lerpC([70, 130, 255], [150, 90, 255], clamp01(x / W)), 0.85, 2.5);
    roundRect(d, 12, 12, W - 24, H - 24, 20, WHITE, 0.07, 1);
    for (const [bx, by, dx, dy] of [[22, 22, 1, 1], [W - 23, 22, -1, 1], [22, H - 23, 1, -1], [W - 23, H - 23, -1, -1]]) bracket(d, bx, by, dx, dy, [80, 150, 255]);

    // ───── الجهة اليسرى: العنوان والصورة والشارة ─────
    text(d, 'MIRA', 50, 45, 17, [225, 238, 255], 'l', 1, 6);
    text(d, 'DEVELOPER CARD', 50, 66, 11, MUTED, 'l', 1, 4);
    avatar(d, 150, 192, 94, img);
    disc(d, 228, 262, 31, [130, 70, 245], 1);
    roundRect(d, 197, 231, 62, 62, 31, WHITE, 0.85, 3);
    text(d, 'LVL', 228, 252, 11, [226, 214, 255], 'c', 1, 2);
    text(d, 'MAX', 228, 272, 19, WHITE, 'c', 1, 0);

    // ───── صف الشارات العلوي ─────
    const cy0 = 22, ch = 40, cs = 16, csp = 1.5, pad = 17, gap = 12, X0 = 290, X1 = 960;
    const specs = [
        ['DEVELOPER', [255, 215, 10], [255, 190, 0], [45, 32, 0]],
        ['LV. MAX', [124, 58, 237], [150, 70, 245], WHITE],
        [`AGE • ${age}`, [59, 130, 246], [40, 100, 235], WHITE]
    ];
    const lastLabel = 'OWNER';
    const widths = specs.map(s => textWidth(s[0], cs, csp) + pad * 2);
    const wLast = textWidth(lastLabel, cs, csp) + pad * 2;
    const flagW = 44, flagH = 28;
    const flagTextW = textWidth(country, cs, csp);
    const wFlag = Math.max(flagW + flagTextW + 44, X1 - X0 - widths.reduce((a, b) => a + b, 0) - wLast - gap * 4);
    let cx0 = X0;
    specs.forEach((s, i) => { chip(d, cx0, cy0, widths[i], ch, s[0], s[1], s[2], s[3], cs, csp); cx0 += widths[i] + gap; });
    roundRect(d, cx0, cy0, wFlag, ch, ch / 2, [8, 16, 42], 0.8);
    roundRect(d, cx0, cy0, wFlag, ch, ch / 2, [120, 160, 255], 0.5, 1.5);
    flagSudan(d, cx0 + 14, cy0 + (ch - flagH) / 2, flagW, flagH);
    text(d, country, cx0 + 14 + flagW + 14, cy0 + ch / 2, cs, WHITE, 'l', 1, csp);
    cx0 += wFlag + gap;
    chip(d, X1 - wLast, cy0, wLast, ch, lastLabel, [250, 204, 21], [251, 146, 60], [60, 30, 0], cs, csp);

    // ───── الاسم ورقم البطاقة ─────
    const nSize = fitSize(name, 50, 460, 1);
    glowText(d, name, 290, 106, nSize, WHITE, CYAN, 'l', 1);
    text(d, '“ MIRA BOT DEVELOPER ”', 290, 146, 19, [150, 178, 225], 'l', 1, 2);
    text(d, 'CARD NO.', 960, 101, 12, MUTED, 'r', 1, 3);
    text(d, idNum, 960, 121, 21, WHITE, 'r', 1, 2);

    // خط فاصل بنقطتين
    for (let x = 290; x <= 960; x++) blend(d, x, 174, [90, 140, 255], 0.75);
    disc(d, 290, 174, 4, [90, 150, 255], 1); disc(d, 960, 174, 4, [90, 150, 255], 1);

    // ───── شريط القوة ─────
    text(d, 'POWER LEVEL', 290, 201, 15, MUTED, 'l', 1, 3);
    text(d, '100%', 960, 201, 15, [255, 180, 80], 'r', 1, 1);
    const bx = 290, bw = 670, by = 218, bh = 26;
    roundRect(d, bx, by, bw, bh, 13, [255, 255, 255], 0.08);
    roundRect(d, bx, by, bw, bh, 13, [120, 160, 255], 0.25, 1.5);
    roundRect(d, bx, by, bw, bh, 13, (x) => {
        const t = clamp01((x - bx) / bw);
        return t < 0.5 ? lerpC([34, 211, 238], [99, 102, 241], t * 2) : lerpC([99, 102, 241], [200, 90, 255], (t - 0.5) * 2);
    }, 1);
    for (let x = bx + 14; x < bx + bw - 14; x++) { blend(d, x, by + 4, WHITE, 0.3); blend(d, x, by + 5, WHITE, 0.12); }
    for (const t of [0.25, 0.5, 0.75]) for (let y = by + 3; y < by + bh - 3; y++) blend(d, bx + bw * t, y, WHITE, 0.25);
    text(d, '∞ / ∞ XP', 290, 266, 15, MUTED, 'l', 1, 1);
    text(d, 'NO LIMITS', 960, 266, 15, MUTED, 'r', 1, 2);

    // ───── ست بطاقات معلومات ─────
    const boxes = [
        ['NAME', name, 'user', [96, 165, 255]],
        ['COUNTRY', country, 'globe', [52, 211, 153]],
        ['AGE', String(age), 'cake', [244, 114, 182]],
        ['ROLE', 'OWNER', 'crown', [168, 85, 247]],
        ['STATUS', 'ACTIVE', 'status', [250, 204, 21]],
        ['BOT', 'MIRA', 'bot', [251, 146, 60]]
    ];
    boxes.forEach(([label, value, ic, col], i) => {
        const x = 40 + i * 156, y = 292, w = 140, h = 108;
        roundRect(d, x, y, w, h, 18, [6, 12, 34], 0.72);
        roundRect(d, x, y, w, h, 18, col, 0.5, 2);
        for (let px = x + 16; px < x + w - 16; px++) { blend(d, px, y + 1, col, 0.95); blend(d, px, y + 2, col, 0.95); blend(d, px, y + 3, col, 0.6); }
        disc(d, x + 34, y + 38, 18, col, 0.2);
        icon(d, ic, x + 34, y + 38, 12, col, 1);
        text(d, label, x + 60, y + 38, 13, col, 'l', 1, 1.5);
        const vs = fitSize(value, 36, w - 32);
        text(d, value, x + 18, y + 78, vs, WHITE, 'l', 1, 0);
    });

    // ───── الشريط السفلي ─────
    barcode(d, 40, 432, 190, 34, idNum);
    text(d, idNum, 40, 478, 10, MUTED, 'l', 1, 2);
    const px0 = 360, pw = 280, py0 = 424, ph = 34;
    roundRect(d, px0, py0, pw, ph, 17, (x) => lerpC([70, 140, 255], [30, 70, 190], clamp01((x - px0) / pw)), 1);
    roundRect(d, px0, py0, pw, ph, 17, WHITE, 0.4, 1.5);
    for (let x = px0 + 18; x < px0 + pw - 18; x++) blend(d, x, py0 + 4, WHITE, 0.25);
    text(d, `DEVELOPER CARD •• ${idNum.slice(-4)}`, px0 + pw / 2, py0 + ph / 2, 15, WHITE, 'c', 1, 2.5);
    text(d, `MIRA DEVELOPER CARD • ${date}`, 500, 474, 12, MUTED, 'c', 1, 2);
    glow(d, 798, 458, 14, GREEN, 0.6);
    disc(d, 798, 458, 4.5, GREEN, 1);
    text(d, 'ACTIVE', 810, 458, 14, GREEN, 'l', 1, 2);

    // شريحة ذهبية
    roundRect(d, 910, 436, 50, 38, 9, (x, y) => lerpC([255, 214, 90], [235, 160, 40], clamp01((y - 436) / 38)), 1);
    roundRect(d, 910, 436, 50, 38, 9, WHITE, 0.4, 1.5);
    roundRect(d, 925, 446, 20, 18, 4, [190, 120, 20], 0.55, 1.5);
    for (let x = 910; x < 960; x++) blend(d, x, 455, [190, 120, 20], 0.5);
    for (let y = 436; y < 474; y++) { blend(d, 925, y, [190, 120, 20], 0.35); blend(d, 945, y, [190, 120, 20], 0.35); }
    return d;
}

/** ترميز PNG بمكتبة zlib المدمجة */
const CRC = (() => { const t = []; for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; t[n] = c >>> 0; } return t; })();
const crc32 = buf => { let c = 0xffffffff; for (const b of buf) c = CRC[(c ^ b) & 255] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; };
function chunk(type, data) {
    const len = Buffer.alloc(4); len.writeUInt32BE(data.length);
    const body = Buffer.concat([Buffer.from(type), data]);
    const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(body));
    return Buffer.concat([len, body, crc]);
}
function encodePng(rgba) {
    const stride = W * 4, raw = Buffer.alloc((stride + 1) * H);
    for (let y = 0; y < H; y++) Buffer.from(rgba.buffer, rgba.byteOffset + y * stride, stride).copy(raw, y * (stride + 1) + 1);
    const ihdr = Buffer.alloc(13); ihdr.writeUInt32BE(W, 0); ihdr.writeUInt32BE(H, 4); ihdr[8] = 8; ihdr[9] = 6;
    return Buffer.concat([Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]), chunk('IHDR', ihdr), chunk('IDAT', zlib.deflateSync(raw, { level: 6 })), chunk('IEND', Buffer.alloc(0))]);
}

/* ═══════════ جلب الصورة ═══════════ */
// تحميل صورة من رابط (مع تتبع التحويلات)، ويمنع التخزين المؤقت
function fetchImage(url, redirects = 5) {
    return new Promise((resolve, reject) => {
        const req = https.get(url, {
            headers: { 'User-Agent': 'Mozilla/5.0', 'Cache-Control': 'no-cache', Pragma: 'no-cache' },
            timeout: 15000
        }, res => {
            if ([301, 302, 303, 307, 308].includes(res.statusCode) && res.headers.location && redirects > 0) {
                res.resume();
                return resolve(fetchImage(res.headers.location, redirects - 1));
            }
            if (res.statusCode !== 200) { res.resume(); return reject(new Error('HTTP ' + res.statusCode)); }
            const chunks = [];
            res.on('data', c => chunks.push(c));
            res.on('end', () => {
                const buf = Buffer.concat(chunks);
                if (buf.length < 500) return reject(new Error('صورة غير صالحة'));
                resolve(buf);
            });
        });
        req.on('timeout', () => req.destroy(new Error('timeout')));
        req.on('error', reject);
    });
}

